from pathlib import Path
from collections import Counter
import gzip,hashlib,importlib.util,json,re,shutil
root=Path.cwd();out=root/'evidence/controls/nats-memory-create-trace-20261008';out.mkdir(exist_ok=True)
results={}
for name in [t+'-nats-memory-create-trace-268' for t in ('fedora','leap','el10')]+['leap-nats-memory-create-trace-269-group']:
 base=root/'results'/name;status=json.loads((base/'status.json').read_text());assert status['exit_code']==0
 log=(base/'tests.log').read_text();assert 'WARNING: DATA RACE' not in log and '--- FAIL:' not in log
 counts=Counter(re.findall(r'^--- (PASS|SKIP|FAIL):',log,re.M))
